                        /** @description How many runs were queued. */
                        jobCount: number;
                        /** @description What the run left out, and why. */
                        skippedArchived: {
                            /** @description Scenarios left out because they are archived. */
                            scenarios: string[];
                            /** @description Targets left out because they are archived. */
                            targets: string[];
                        };
